import hashlib, subprocess, shutil, os
LEAN="def blend (S f g : Nat → Prop) (h : Nat) := (S h ∧ f h) ∨ (¬ S h ∧ g h)\ndef eventual (x : Nat → Prop) := ∃ H, ∀ h, H ≤ h → x h\ndef gate (a b j : Nat) (p q : Nat → Prop) (h : Nat) :=\n (∀ u, u+a+b+1 ≤ h → p u) ∧\n (∀ g, g+a+1 ≤ h → q g ∨ ∀ f, j ≤ f → f < g → ¬ q f)\ndef dbtrace (a b k : Nat) (S : Nat → Prop) (h : Nat) :=\n (S h ∧ h < k) ∨ (¬ S h ∧ h < a+b+1)\ndef bad (j : Nat) (d : Nat → Prop) (g : Nat) := ¬ d g ∧ ∃ f, j ≤ f ∧ f < g ∧ d f\n\ntheorem self_law (a b j k : Nat) (hk : 1 ≤ k) (S d x : Nat → Prop)\n (eqn : ∀ h, x h ↔ blend S (fun h => ∀ u, u+k ≤ h → x u) (gate a b j x d) h) :\n eventual x ↔ ∀ g, bad j d g → ∀ h, g+a+1 ≤ h → S h := by\n classical\n constructor\n · intro ⟨H,hH⟩ g ⟨nd, f,jf,fg,df⟩ h gh\n   apply Classical.byContradiction\n   intro ns\n   have nx : ¬ x h := by\n     intro xh\n     rcases (eqn h).1 xh with ⟨sh,_⟩ | ⟨_,_,hh⟩\n     · exact ns sh\n     · rcases hh g gh with dg | rest\n       · exact nd dg\n       · exact rest f jf fg df\n   let z := H+h+a+b+k+1\n   rcases (eqn z).1 (hH z (by dsimp [z]; omega)) with ⟨_,hh⟩ | ⟨_,hh,_⟩\n   · exact nx (hh h (by dsimp [z]; omega))\n   · exact nx (hh h (by dsimp [z]; omega))\n · intro good\n   have allx : ∀ h, x h := by\n     intro h\n     induction h using Nat.strongRecOn with\n     | ind h ih =>\n       apply (eqn h).2\n       by_cases sh : S h\n       · exact Or.inl ⟨sh, fun u uh => ih u (by omega)⟩\n       · refine Or.inr ⟨sh, (fun u uh => ih u (by omega)), ?_⟩\n         intro g gh\n         by_cases dg : d g\n         · exact Or.inl dg\n         · exact Or.inr (fun f jf fg df => sh (good g ⟨dg,f,jf,fg,df⟩ h gh))\n   exact ⟨0,fun h _ => allx h⟩\n\ntheorem finite_law (a b j k M : Nat) (hk : 1 ≤ k) (S x : Nat → Prop)\n (fin : ∀ h, M ≤ h → ¬ S h)\n (eqn : ∀ h, x h ↔ blend S (fun h => ∀ u, u+k ≤ h → x u)\n   (gate a b j x (dbtrace a b k S)) h) :\n eventual x ↔ ∀ f, j ≤ f → ¬ dbtrace a b k S f := by\n classical\n rw [self_law a b j k hk S _ x eqn]\n constructor\n · intro good f jf df\n   let g := f+a+b+k+1\n   have nd : ¬ dbtrace a b k S g := by\n     intro dd; rcases dd with ⟨_,e⟩ | ⟨_,e⟩ <;> dsimp [g] at e <;> omega\n   have bg : bad j (dbtrace a b k S) g := ⟨nd,f,jf,by dsimp [g]; omega,df⟩\n   exact fin (M+g+a+1) (by omega) (good g bg _ (by omega))\n · intro good g ⟨_,f,jf,_,df⟩\n   exact False.elim (good f jf df)\n\ntheorem interval_law (a b j k : Nat) (jm : j ≤ a+b) (S : Nat → Prop) :\n (∀ f, j ≤ f → ¬ dbtrace a b k S f) ↔\n k ≤ j ∧ (∀ f, j ≤ f → f ≤ a+b → S f) := by\n classical\n constructor\n · intro H\n   have sj : S j := by\n     apply Classical.byContradiction\n     intro ns\n     exact H j (by omega) (Or.inr ⟨ns,by omega⟩)\n   constructor\n   · apply Classical.byContradiction\n     intro nk\n     exact H j (by omega) (Or.inl ⟨sj,by omega⟩)\n   · intro f jf fm\n     apply Classical.byContradiction\n     intro ns\n     exact H f jf (Or.inr ⟨ns,by omega⟩)\n · intro ⟨kj,allS⟩ f jf dd\n   rcases dd with ⟨_,fk⟩ | ⟨ns,fm⟩\n   · omega\n   · exact ns (allS f jf (by omega))\n\ntheorem db_semantics (a b j k : Nat) (S : Nat → Prop) (h : Nat) :\n blend S (fun h => ∀ u, u+k ≤ h → False) (gate a b j (fun _ => False) (fun _ => False)) h\n ↔ dbtrace a b k S h := by\n have hh (m : Nat) : (∀ u, u+m ≤ h → False) ↔ h < m := by\n   constructor\n   · intro H; apply Classical.byContradiction; intro e; exact H 0 (by omega)\n   · intro H u uh; omega\n simp only [blend,gate,dbtrace,hh]\n simp only [Nat.add_assoc] at *\n simp only [hh, false_or, not_false_eq_true, implies_true, and_true]\n\ntheorem unexploitable (a b j k : Nat) (S p q x : Nat → Prop)\n (eqn : ∀ h, x h ↔ blend S (fun h => ∀ u, u+k ≤ h → p u) (gate a b j p q) h)\n (pd : eventual (fun h => ¬ p h)) : eventual (fun h => ¬ x h) := by\n obtain ⟨H,hH⟩ := pd\n refine ⟨H+a+b+k+1, ?_⟩\n intro h hh xh\n rcases (eqn h).1 xh with ⟨_,hf⟩ | ⟨_,hp,_⟩\n · exact hH H (by omega) (hf H (by omega))\n · exact hH H (by omega) (hp H (by omega))\n\ntheorem fb_partner (a b j k : Nat) (hj : 1 ≤ j) (hk : 1 ≤ k) (S x y : Nat → Prop)\n (ex : ∀ h, x h ↔ blend S (fun h => ∀ u, u+k ≤ h → y u) (gate a b j y (fun g => g=0)) h)\n (ey : ∀ h, y h ↔ ∀ u, u < h → x u) : ∀ h, x h ∧ y h := by\n classical\n intro h\n induction h using Nat.strongRecOn with\n | ind h ih =>\n   constructor\n   · apply (ex h).2\n     by_cases sh : S h\n     · exact Or.inl ⟨sh,fun u uh => (ih u (by omega)).2⟩\n     · exact Or.inr ⟨sh,(fun u uh => (ih u (by omega)).2),fun g _ => Or.inr (fun f jf _ e => by omega)⟩\n   · exact (ey h).2 (fun u uh => (ih u uh).1)\n\ntheorem cb_partner (a b j k : Nat) (S : Nat → Prop) :\n ∀ h, blend S (fun h => ∀ u, u+k ≤ h → True) (gate a b j (fun _ => True) (fun _ => True)) h := by\n classical\n intro h\n by_cases sh : S h\n · exact Or.inl ⟨sh,fun _ _ => trivial⟩\n · exact Or.inr ⟨sh,(fun _ _ => trivial),fun _ _ => Or.inl trivial⟩\n#print axioms self_law\n#print axioms finite_law\n#print axioms interval_law\n#print axioms db_semantics\n#print axioms unexploitable\n#print axioms fb_partner\n#print axioms cb_partner\n\ndef bx (φ : Nat → Prop) : Nat → Prop := fun h => ∀ g, g < h → φ g\ndef bxn : Nat → (Nat → Prop) → (Nat → Prop)\n  | 0, φ => φ\n  | n+1, φ => bx (bxn n φ)\n\ntheorem bxn_succ_iff (n : Nat) (φ : Nat → Prop) (h : Nat) :\n    bxn (n+1) φ h ↔ ∀ g, g + (n+1) ≤ h → φ g := by\n  induction n generalizing h with\n  | zero =>\n    simp only [bxn, bx]\n    exact ⟨fun H g hg => H g (by omega), fun H g hg => H g (by omega)⟩\n  | succ n ih =>\n    show bx (bxn (n+1) φ) h ↔ _\n    simp only [bx]\n    constructor\n    · intro H g hg\n      exact (ih (h-1)).1 (H (h-1) (by omega)) g (by omega)\n    · intro H g' hg'\n      exact (ih g').2 (fun g hg => H g (by omega))\n\ntheorem bxn_iff (n : Nat) (hn : 1 ≤ n) (φ : Nat → Prop) (h : Nat) :\n    bxn n φ h ↔ ∀ g, g + n ≤ h → φ g := by\n  obtain ⟨m, rfl⟩ : ∃ m, n = m + 1 := ⟨n - 1, by omega⟩\n  exact bxn_succ_iff m φ h\n\ndef botn (n : Nat) : Nat → Prop := bxn n (fun _ => False)\n\ntheorem botn_iff (n h : Nat) : botn n h ↔ h < n := by\n  cases n with\n  | zero => simp [botn, bxn]\n  | succ m =>\n    unfold botn; rw [bxn_succ_iff]\n    constructor\n    · intro H; apply Classical.byContradiction; intro hn\n      exact H 0 (by omega)\n    · intro hlt g hg; omega\n\n\ntheorem normalized (a b j : Nat) (p q : Nat → Prop) (h : Nat) :\n bxn (a+1) (fun g => bxn b p g ∧ (q g ∨ bx (fun f => botn j f ∨ ¬ q f) g)) h\n ↔ gate a b j p q h := by\n classical\n rw [bxn_succ_iff]\n constructor\n · intro H\n   constructor\n   · intro u uh\n     have hp := (H (u+b) (by omega)).1\n     cases b with\n     | zero => exact hp\n     | succ c => exact (bxn_succ_iff c p (u+(c+1))).1 hp u (by omega)\n   · intro g gh\n     rcases (H g (by omega)).2 with dq | hh\n     · exact Or.inl dq\n     · apply Or.inr\n       intro f jf fg\n       rcases hh f fg with bf | nf\n       · have := (botn_iff j f).1 bf; omega\n       · exact nf\n · intro ⟨hp,hq⟩ g gh\n   constructor\n   · cases b with\n     | zero => exact hp g (by omega)\n     | succ c =>\n       apply (bxn_succ_iff c p g).2\n       intro u ug\n       exact hp u (by omega)\n   · rcases hq g (by omega) with dq | hh\n     · exact Or.inl dq\n     · apply Or.inr\n       intro f fg\n       by_cases fj : f < j\n       · exact Or.inl ((botn_iff j f).2 fj)\n       · exact Or.inr (hh f (by omega) fg)\n#print axioms normalized\ntheorem finite_interval (a b j k M : Nat) (hk : 1 ≤ k) (jm : j ≤ a+b) (S x : Nat → Prop)\n (fin : ∀ h, M ≤ h → ¬ S h)\n (eqn : ∀ h, x h ↔ blend S (fun h => ∀ u, u+k ≤ h → x u)\n   (gate a b j x (dbtrace a b k S)) h) :\n eventual x ↔ k ≤ j ∧ (∀ f, j ≤ f → f ≤ a+b → S f) := by\n rw [finite_law a b j k M hk S x fin eqn]\n exact interval_law a b j k jm S\n#print axioms finite_interval\n"
assert hashlib.sha256(LEAN.encode()).hexdigest()=='45203eb79f5cf240060022a42a7a62c52ba2b6737e4e6250b6e4edab9fa93a92'
binary = next((p for p in (shutil.which('lean'), '/opt/elan/bin/lean', os.path.expanduser('~/.elan/bin/lean')) if p and os.path.exists(p)), None)
assert binary, 'Lean missing'
r=subprocess.run([binary,'--stdin'],input=LEAN,text=True,capture_output=True,timeout=60)
assert r.returncode==0,r.stdout+r.stderr
assert 'sorryAx' not in r.stdout and r.stdout.count('axioms')==9
for old,new in [('k ≤ j ∧','k < j ∧'),('g+a+1 ≤ h → S h','g+a ≤ h → S h'),('(hj : 1 ≤ j)','(hj : 0 ≤ j)')]:
 bad=LEAN.replace(old,new)
 assert bad!=LEAN
 r=subprocess.run([binary,'--stdin'],input=bad,text=True,capture_output=True,timeout=15)
 assert r.returncode!=0,'mutation accepted'
print('PASS: 9 Lean theorems including literal J normalization; 3 mutations rejected')
